5940: function ConvertFrom-CompactDuration {
5941:     param([string]$Text)
5942:     $total = [double]0
5943:     $any = $false
5944:     foreach ($p in $script:RetryAfterRe.CompactPart.Matches([string]$Text)) {
5945:         $n = [double]::Parse($p.Groups['n'].Value, $script:Invariant)
5946:         switch ($p.Groups['u'].Value.ToLowerInvariant()) {
5947:             'w' { $total += $n * 604800 }
5948:             'd' { $total += $n * 86400 }
5949:             'h' { $total += $n * 3600 }
5950:             'm' { $total += $n * 60 }
5951:             'ms' { $total += $n / 1000 }
5952:             default { $total += $n }
5953:         }
5954:         $any = $true
5955:     }
5956:     if (-not $any) { return $null }
5957:     return $total
5958: }
5959: function ConvertTo-DurationSeconds {
5960:     param([long]$N, [string]$Unit)
5961:     $u = ([string]$Unit).ToLowerInvariant()
5962:     if ($u.StartsWith('w')) { return $N * 604800 }
5963:     if ($u.StartsWith('d')) { return $N * 86400 }
5964:     if ($u.StartsWith('h')) { return $N * 3600 }
5965:     if ($u.StartsWith('m')) { return $N * 60 }
5966:     return $N
5967: }
